css:
.serendicity-sim-container {
    padding: 20px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce3ed 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

.serendicity-sim-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 30px;
    border-radius: 20px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(26,58,92,0.3);
    text-align: center;
}

.serendicity-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.8rem;
    font-weight: 700;
}

.serendicity-sim-subtitle {
    margin: 0;
    font-size: 1rem;
    opacity: 0.85;
}

.serendicity-sim-period-counter {
    text-align: center;
    font-size: 1.1rem;
    color: #1a3a5c;
    font-weight: 600;
    margin-bottom: 20px;
}

.serendicity-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(5, 1fr);
    gap: 14px;
    margin-bottom: 24px;
}

.serendicity-sim-status-card {
    background: white;
    border-radius: 14px;
    padding: 18px 12px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    transition: transform 0.3s ease;
    text-align: center;
    border-top: 4px solid #2c5f8a;
}

.serendicity-sim-status-card:hover {
    transform: translateY(-4px);
}

.serendicity-card-revenue { border-top-color: #2c5f8a; }
.serendicity-card-ebitda { border-top-color: #27ae60; }
.serendicity-card-capital { border-top-color: #e67e22; }
.serendicity-card-exploration { border-top-color: #8e44ad; }
.serendicity-card-adapt { border-top-color: #16a085; }

.serendicity-sim-label {
    color: #666;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.serendicity-sim-value {
    font-size: 1.6rem;
    font-weight: 700;
    color: #1a3a5c;
}

.serendicity-sim-briefing {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    border-left: 5px solid #2c5f8a;
}

.serendicity-sim-briefing h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 12px;
    font-size: 1.15rem;
}

.serendicity-sim-briefing-text {
    color: #444;
    line-height: 1.65;
    font-size: 0.95rem;
}

.serendicity-sim-event-panel {
    background: linear-gradient(135deg, #fff3cd 0%, #ffeaa7 100%);
    border-radius: 14px;
    padding: 20px;
    margin-bottom: 20px;
    border-left: 5px solid #e67e22;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.serendicity-sim-event-panel h4 {
    color: #856404;
    margin-top: 0;
    margin-bottom: 10px;
}

.serendicity-sim-controls {
    background: white;
    border-radius: 14px;
    padding: 24px;
    margin-bottom: 24px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
}

.serendicity-sim-controls h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 16px;
    font-size: 1.1rem;
}

.serendicity-sim-decision-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 18px;
}

.serendicity-sim-decision-group label {
    display: block;
    font-weight: 600;
    color: #1a3a5c;
    margin-bottom: 6px;
    font-size: 0.9rem;
}

.serendicity-sim-select {
    font-size: 0.88rem;
    padding: 10px;
    border: 2px solid #dce3ed;
    border-radius: 8px;
    transition: border-color 0.3s;
}

.serendicity-sim-select:focus {
    border-color: #2c5f8a;
    box-shadow: 0 0 0 3px rgba(44,95,138,0.15);
}

.serendicity-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
}

.serendicity-sim-submit {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    border: none;
    padding: 12px 32px;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 10px;
    box-shadow: 0 4px 12px rgba(26,58,92,0.3);
    transition: transform 0.2s, box-shadow 0.2s;
}

.serendicity-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 16px rgba(26,58,92,0.4);
}

.serendicity-sim-history {
    margin-bottom: 24px;
}

.serendicity-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
}

.serendicity-sim-chart-wrapper {
    background: white;
    border-radius: 14px;
    padding: 20px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.08);
    min-height: 280px;
}

@media (max-width: 992px) {
    .serendicity-sim-status-cards {
        grid-template-columns: repeat(3, 1fr);
    }
    .serendicity-sim-charts {
        grid-template-columns: 1fr;
    }
}

@media (max-width: 768px) {
    .serendicity-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .serendicity-sim-decision-row {
        grid-template-columns: 1fr;
    }
}

