        _lang() {
            var l = (window.mySimulation && window.mySimulation.language) ||
                    (document.documentElement && document.documentElement.lang) || 'en';
            return (l === 'es') ? 'es' : 'en';
        }

        // Language-resolved content for a round (1-based period).
        _L(period) {
            var idx = Math.min((period || 1) - 1, this.ROUNDS.length - 1);
            var r = this.ROUNDS[idx];
            return r[this._lang()] || r.en;
        }

        _t(key, params) {
            if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                return window.mySimulation.t(key, params);
            }
            return key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue: 800,
                    ebitda: 224,
                    capitalRemaining: 55,
                    explorationValue: 0,
                    adaptabilityScore: 0,
                    miningRevenue: 440,
                    nonCommodityRevenue: 360,
                    ebitdaMargin: 28,
                    slackLevel: 0,
                    terraMetricsInvested: false,
                    terraMetricsAmount: 0,
                    cumulativeFinancialImpact: 0,
                    revenueHistory: [],
                    ebitdaHistory: [],
                    miningHistory: [],
                    nonCommodityHistory: [],
                    eventLog: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    primaryChoice: 0,
                    secondaryChoice: 0
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            // Read the learner's current selections. IMPORTANT: do NOT rebuild the
            // selects here — rebuilding resets each <select> to option 0 and would
            // discard the learner's choice. The briefing/selects for the next round
            // are rendered at the end of calculateResults instead.
            var primaryEl = document.getElementById('primarySelect');
            if (primaryEl) {
                var pv = parseInt(primaryEl.value, 10);
                decisions.primaryChoice = Number.isFinite(pv) ? pv : 0;
            }

            var secondaryEl = document.getElementById('secondarySelect');
            if (secondaryEl) {
                var sv = parseInt(secondaryEl.value, 10);
                decisions.secondaryChoice = Number.isFinite(sv) ? sv : 0;
            }

            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;
            var roundIdx = round - 1;
            var alloc = this.ROUND_ALLOCATIONS[roundIdx] || 0;

            var ebitdaDelta = 0;
            var revenueDelta = 0;
            var explorationGain = 0;
            var adaptGain = 0;
            var eventMessage = '';
            var eventTriggered = false;

            ds.capitalRemaining -= alloc;

            if (round === 1) {
                var r1Primary = [
                    { ebitda: 3.2, exploration: 0 },
                    { ebitda: 2.2, exploration: 0.8 },
                    { ebitda: 1.3, exploration: 1.8 },
                    { ebitda: -0.1, exploration: 2.5 }
                ];
                var r1Adapt = [0, 5, 10, 15];
                var pick = r1Primary[d.primaryChoice] || r1Primary[0];
                ebitdaDelta = pick.ebitda;
                explorationGain = pick.exploration;
                adaptGain = r1Adapt[d.secondaryChoice] || 0;
                ds.slackLevel = d.secondaryChoice;

                if (Math.random() < 0.60) {
                    eventTriggered = true;
                    var slackBonus = ds.slackLevel * 1.5;
                    ebitdaDelta -= (5 - slackBonus);
                    eventMessage = this._t('evt_r1_commodity');
                    if (ds.slackLevel >= 2) {
                        eventMessage += '<br>' + this._t('evt_r1_slack_help');
                        adaptGain += 3;
                    }
                }
            }

            if (round === 2) {
                var r2Impacts = [
                    { ebitda: -6.0, exploration: 3.0, terraAmt: 20 },
                    { ebitda: -2.8, exploration: 2.0, terraAmt: 12 },
                    { ebitda: -0.4, exploration: 1.2, terraAmt: 3 },
                    { ebitda: 0, exploration: 0, terraAmt: 0 }
                ];
                var r2Adapt = [4, 6, 3, 0];
                var pick2 = r2Impacts[d.primaryChoice] || r2Impacts[3];
                ebitdaDelta = pick2.ebitda;
                explorationGain = pick2.exploration;
                adaptGain = r2Adapt[d.primaryChoice] || 0;

                if (d.primaryChoice < 3) {
                    ds.terraMetricsInvested = true;
                    ds.terraMetricsAmount = pick2.terraAmt;
                }

                var integrationAdapt = [2, 4, 2, 0];
                adaptGain += integrationAdapt[d.secondaryChoice] || 0;

                if (ds.slackLevel >= 2) {
                    explorationGain += 0.5;
                    adaptGain += 2;
                }

                if (Math.random() < 0.55) {
                    eventTriggered = true;
                    if (ds.terraMetricsInvested) {
                        if (Math.random() < 0.55) {
                            ebitdaDelta += 1.5;
                            eventMessage = this._t('evt_r2_dd_positive');
                        } else {
                            ebitdaDelta -= 1.0;
                            eventMessage = this._t('evt_r2_dd_concern');
                        }
                    } else {
                        eventMessage = this._t('evt_r2_passed');
                        explorationGain -= 0.3;
                    }
                }
            }

            if (round === 3) {
                var r3Primary = [
                    { ebitda: -38, revDelta: -30 },
                    { ebitda: -15, revDelta: -10 },
                    { ebitda: -12, revDelta: -5 },
                    { ebitda: -25, revDelta: -20 }
                ];
                var r3Secondary = [
                    { adapt: 0, explorationMod: -1.0 },
                    { adapt: 4, explorationMod: 0 },
                    { adapt: 8, explorationMod: 1.0 },
                    { adapt: 10, explorationMod: 1.5 }
                ];
                var pick3p = r3Primary[d.primaryChoice] || r3Primary[1];
                var pick3s = r3Secondary[d.secondaryChoice] || r3Secondary[1];

                ebitdaDelta = pick3p.ebitda + (ds.slackLevel * 2);
                revenueDelta = pick3p.revDelta;
                ds.miningRevenue += revenueDelta;
                adaptGain = pick3s.adapt;
                explorationGain = pick3s.explorationMod;

                if (ds.terraMetricsInvested) {
                    ebitdaDelta += 2;
                    explorationGain += 0.8;
                    adaptGain += 2;
                }

                if (Math.random() < 0.60) {
                    eventTriggered = true;
                    ebitdaDelta -= 4;
                    eventMessage = this._t('evt_r3_regulatory');
                    if (d.secondaryChoice >= 2) {
                        eventMessage += '<br>' + this._t('evt_r3_growth_positioned');
                        adaptGain += 3;
                    }
                }
            }

            if (round === 4) {
                var structuralShift = Math.random() < 0.55;
                var r4Primary = [
                    { ebitdaCyclical: 8, ebitdaStructural: -10 },
                    { ebitdaCyclical: -5, ebitdaStructural: 6 },
                    { ebitdaCyclical: 2, ebitdaStructural: 2 },
                    { ebitdaCyclical: -8, ebitdaStructural: 10 }
                ];
                var r4Adapt = [2, 6, 8, 5];
                var pick4 = r4Primary[d.primaryChoice] || r4Primary[2];

                if (structuralShift) {
                    ebitdaDelta = pick4.ebitdaStructural;
                } else {
                    ebitdaDelta = pick4.ebitdaCyclical;
                }

                adaptGain = r4Adapt[d.primaryChoice] || 0;

                var r4SecondaryExpl = [0, 1.5, 2.0, 3.0];
                explorationGain = r4SecondaryExpl[d.secondaryChoice] || 0;

                if (ds.terraMetricsInvested) {
                    explorationGain += 1.0;
                    ebitdaDelta += 1.5;
                }
                if (ds.slackLevel >= 2) {
                    adaptGain += 3;
                }

                eventTriggered = true;
                if ((d.primaryChoice === 0 && structuralShift) || (d.primaryChoice >= 1 && !structuralShift)) {
                    eventMessage = this._t('evt_r4_counter') + ' ' +
                        (structuralShift ? this._t('evt_r4_counter_structural') : this._t('evt_r4_counter_cyclical'));
                    adaptGain += 2;
                } else {
                    eventMessage = this._t('evt_r4_confirm') + ' ' +
                        (structuralShift ? this._t('evt_r4_confirm_structural') : this._t('evt_r4_confirm_cyclical'));
                    ebitdaDelta += 3;
                }
            }

            if (round === 5) {
                var r5ExplBudget = [1.0, 2.0, 3.0, 4.0];
                var r5GovAdapt = [3, 6, 8, 5];
                explorationGain = r5ExplBudget[d.primaryChoice] || 0;
                adaptGain = r5GovAdapt[d.secondaryChoice] || 0;

                var coherenceBonus = 0;
                if (ds.slackLevel >= 2 && d.primaryChoice >= 2) coherenceBonus += 4;
                if (ds.terraMetricsInvested && d.primaryChoice >= 1) coherenceBonus += 3;
                if (ds.slackLevel < 2 && d.primaryChoice < 2) coherenceBonus += 3;
                adaptGain += coherenceBonus;

                ebitdaDelta = ds.explorationValue * 0.4;
                revenueDelta = ds.explorationValue * 1.2;
                ds.nonCommodityRevenue += revenueDelta;
            }

            ds.ebitda += ebitdaDelta;
            ds.revenue += revenueDelta;
            ds.explorationValue += explorationGain;
            ds.adaptabilityScore += adaptGain;
            ds.cumulativeFinancialImpact += ebitdaDelta;
            ds.ebitdaMargin = Math.round((ds.ebitda / ds.revenue) * 100 * 10) / 10;

            ds.revenueHistory.push(Math.round(ds.revenue * 10) / 10);
            ds.ebitdaHistory.push(Math.round(ds.ebitda * 10) / 10);
            ds.miningHistory.push(Math.round(ds.miningRevenue * 10) / 10);
            ds.nonCommodityHistory.push(Math.round(ds.nonCommodityRevenue * 10) / 10);

            // platform score: same composite as getPerformanceSummary (portfolio plus adaptability plus coherence), clamped to 0-100
            var runningEbitdaChange = ds.ebitda - 224;
            var runningPortfolioScore = Math.min(35, Math.max(-35, Math.round((runningEbitdaChange / 224) * 100)));
            var runningAdaptScore = Math.min(35, Math.round(ds.adaptabilityScore * 0.6));
            var runningCoherenceScore = Math.min(30, Math.round(ds.explorationValue * 3));
            var overallScore = Math.max(0, Math.min(100, runningPortfolioScore + runningAdaptScore + runningCoherenceScore));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });

            if (eventTriggered && eventMessage) {
                ds.eventLog.push(eventMessage);
            }

            var eventEl = document.getElementById('eventPanel');
            var eventTextEl = document.getElementById('eventText');
            if (eventEl && eventTextEl) {
                if (eventTriggered && eventMessage) {
                    eventEl.style.display = 'block';
                    eventTextEl.innerHTML = eventMessage;
                } else {
                    eventEl.style.display = 'none';
                }
            }

            // Render the next round's briefing/selects synchronously (no setTimeout
            // race). currentPeriod is still the round just played; +1 targets the next.
            this._updateBriefing({ currentPeriod: state.currentPeriod + 1, _keepEvent: true });

            return {
                period: state.currentPeriod,
                roundName: this._L(round).title,
                primaryChoice: d.primaryChoice,
                secondaryChoice: d.secondaryChoice,
                ebitdaDelta: Math.round(ebitdaDelta * 10) / 10,
                explorationGain: Math.round(explorationGain * 10) / 10,
                adaptGain: Math.round(adaptGain),
                revenue: Math.round(ds.revenue * 10) / 10,
                ebitda: Math.round(ds.ebitda * 10) / 10,
                capitalRemaining: Math.round(ds.capitalRemaining * 10) / 10,
                explorationValue: Math.round(ds.explorationValue * 10) / 10,
                adaptabilityScore: Math.round(ds.adaptabilityScore),
                eventTriggered: eventTriggered
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.revenue',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('ebitdaDisplay', 'domainState.ebitda',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('capitalDisplay', 'domainState.capitalRemaining',
                (v) => '$' + Math.round(v).toLocaleString() + 'M');
            uiManager.bind('explorationDisplay', 'domainState.explorationValue',
                (v) => '$' + (Math.round(v * 10) / 10).toLocaleString() + 'M');
            uiManager.bind('adaptabilityDisplay', 'domainState.adaptabilityScore',
                (v) => Math.round(v) + ' pts');
        }

