        _updateBriefing(state) {
            var period = state.currentPeriod || 1;
            var L = this._L(period);

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = L.title;

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = L.briefing;

            var primaryLabel = document.getElementById('primaryLabelEl');
            if (primaryLabel) primaryLabel.textContent = L.primaryLabel;

            var secondaryLabel = document.getElementById('secondaryLabelEl');
            if (secondaryLabel) secondaryLabel.textContent = L.secondaryLabel;

            var ord = this.OPTION_ORDER[Math.min(period - 1, this.OPTION_ORDER.length - 1)] || {};
            var shown = function(order, n) {
                return (order && order.length === n) ? order : Array.apply(null, Array(n)).map(function(x, k) { return k; });
            };

            var primarySelect = document.getElementById('primarySelect');
            if (primarySelect) {
                primarySelect.innerHTML = '';
                var po = shown(ord.primary, L.primaryOptions.length);
                for (var pi = 0; pi < po.length; pi++) {
                    var i = po[pi];
                    var opt = document.createElement('option');
                    opt.value = i;
                    opt.textContent = L.primaryOptions[i];
                    primarySelect.appendChild(opt);
                }
            }

            var secondarySelect = document.getElementById('secondarySelect');
            if (secondarySelect) {
                secondarySelect.innerHTML = '';
                var so = shown(ord.secondary, L.secondaryOptions.length);
                for (var si = 0; si < so.length; si++) {
                    var j = so[si];
                    var opt2 = document.createElement('option');
                    opt2.value = j;
                    opt2.textContent = L.secondaryOptions[j];
                    secondarySelect.appendChild(opt2);
                }
            }

            // Only auto-hide the event panel on the very first render; once a round
            // has produced an event we keep it visible until the next result.
            var eventPanel = document.getElementById('eventPanel');
            if (eventPanel && period === 1 && !state._keepEvent) {
                eventPanel.style.display = 'none';
            }
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new SerendiCityAdapter(), {
            simulationType: 'serendicity_strategy',
            maxPeriods: 5,
            autoSaveInterval: 30000
        });
    });

